import React from "react";
import { ShoppingBag, Menu, X, Moon, Sun } from "lucide-react";
import JewelArt from "./JewelArt";
import { COLORS, FONT_DISPLAY, THEME_MODES } from "../constants/theme";

export default function Nav({
  scrolled,
  menuOpen,
  setMenuOpen,
  cartOpen,
  setCartOpen,
  cartCount,
  bump,
  scrollTo,
  setFilter,
  themeMode,
  toggleTheme,
}) {
  const navTextColor = scrolled ? COLORS.text : COLORS.textOnStrong;
  const nextThemeLabel = themeMode === THEME_MODES.DARK ? "light" : "dark";
  const HEADER_HEIGHT = 64; // keep in sync with the actual rendered header row height

  const handleMobileNav = (id) => {
    scrollTo(id);
    setMenuOpen(false);
  };

  return (
    <header
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        zIndex: 50,
        background: scrolled || menuOpen ? COLORS.surfaceBase : "transparent",
        borderBottom: scrolled || menuOpen ? `1px solid ${COLORS.border}` : "1px solid transparent",
        backdropFilter: "blur(18px)",
        WebkitBackdropFilter: "blur(18px)",
        transition: "background 0.3s ease, border-color 0.3s ease",
      }}
    >
      <div
        style={{ maxWidth: 1240, margin: "0 auto", height: HEADER_HEIGHT }}
        className="flex items-center justify-between px-4 sm:px-6 md:px-10"
      >
        <a
          href="#top"
          style={{
            fontFamily: FONT_DISPLAY,
            fontSize: 20,
            letterSpacing: "0.04em",
            color: menuOpen ? COLORS.text : navTextColor,
            display: "flex",
            alignItems: "center",
            gap: 8,
            padding: "16px 0",
          }}
        >
          <JewelArt type="ring" style={{ width: 22, height: 22 }} />
          Nyasa
        </a>

        <nav className="hidden md:flex items-center" style={{ gap: 32 }}>
          {["Rings", "Necklaces", "Earrings"].map((c) => (
            <button
              key={c}
              onClick={() => scrollTo("shop")}
              className="underline-grow"
              style={{
                background: "none",
                border: "none",
                fontSize: 14,
                letterSpacing: "0.03em",
                color: navTextColor,
              }}
            >
              {c}
            </button>
          ))}
          <button
            onClick={() => scrollTo("craft")}
            className="underline-grow"
            style={{ background: "none", border: "none", fontSize: 14, letterSpacing: "0.03em", color: navTextColor }}
          >
            The Craft
          </button>
          <button
            onClick={() => scrollTo("faq")}
            className="underline-grow"
            style={{ background: "none", border: "none", fontSize: 14, letterSpacing: "0.03em", color: navTextColor }}
          >
            FAQ
          </button>
        </nav>

        <div className="flex items-center" style={{ gap: 10 }}>
          <button
            onClick={toggleTheme}
            aria-label={`Switch to ${nextThemeLabel} theme`}
            title={`Switch to ${nextThemeLabel} theme`}
            style={{
              width: 40,
              height: 40,
              borderRadius: 999,
              border: `1px solid ${scrolled || menuOpen ? COLORS.border : COLORS.toggleBorder}`,
              background: scrolled || menuOpen ? COLORS.surfaceSoft : COLORS.toggleSurface,
              color: menuOpen ? COLORS.text : navTextColor,
              display: "inline-flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
              boxShadow: scrolled || menuOpen ? "none" : "0 8px 24px rgba(15, 23, 42, 0.12)",
              transition: "background 0.3s ease, border-color 0.3s ease, color 0.3s ease",
            }}
          >
            {themeMode === THEME_MODES.DARK ? <Sun size={18} strokeWidth={1.7} /> : <Moon size={18} strokeWidth={1.7} />}
          </button>
          <button
            onClick={() => setCartOpen(true)}
            aria-label="Open cart"
            style={{
              background: "none",
              border: "none",
              position: "relative",
              color: menuOpen ? COLORS.text : navTextColor,
              padding: 8,
              flexShrink: 0,
            }}
          >
            <ShoppingBag size={20} strokeWidth={1.6} />
            {cartCount > 0 && (
              <span
                className={bump ? "cart-badge-bump" : ""}
                style={{
                  position: "absolute",
                  top: 2,
                  right: 2,
                  background: COLORS.rust,
                  color: COLORS.textOnStrong,
                  fontSize: 10,
                  width: 16,
                  height: 16,
                  borderRadius: "50%",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                {cartCount}
              </span>
            )}
          </button>
          <button
            className="md:hidden"
            onClick={() => setMenuOpen((v) => !v)}
            aria-label="Toggle menu"
            aria-expanded={menuOpen}
            style={{
              background: "none",
              border: "none",
              color: menuOpen ? COLORS.text : navTextColor,
              padding: 8,
              minHeight: 44,
              minWidth: 44,
              flexShrink: 0,
              display: "inline-flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            {menuOpen ? <X size={22} strokeWidth={1.6} /> : <Menu size={22} strokeWidth={1.6} />}
          </button>
        </div>
      </div>

      {menuOpen && (
        <>
          {/* Backdrop overlay — fixed to viewport, sits below the dropdown panel */}
          <div
            className="md:hidden"
            onClick={() => setMenuOpen(false)}
            style={{
              position: "fixed",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              background: "rgba(0,0,0,0.45)",
              zIndex: 999,
            }}
          />

          {/* Dropdown panel — fixed to the viewport (not the header box), fully opaque,
              and pinned to a very high z-index so it can't lose to any stray
              stacking context created elsewhere on the page. */}
          <div
            className="md:hidden"
            style={{
              position: "fixed",
              top: HEADER_HEIGHT,
              left: 0,
              right: 0,
              zIndex: 1000,
              background: COLORS.surfaceBase || "#ffffff",
              borderTop: `1px solid ${COLORS.border}`,
              boxShadow: "0 16px 32px rgba(0,0,0,0.25)",
            }}
          >
            <nav
              className="flex flex-col px-6"
              style={{ paddingTop: 8, paddingBottom: 24 }}
            >
              {["Rings", "Necklaces", "Earrings"].map((c) => (
                <button
                  key={c}
                  onClick={() => handleMobileNav("shop")}
                  style={{
                    display: "block",
                    width: "100%",
                    textAlign: "left",
                    padding: "14px 0",
                    background: "none",
                    border: "none",
                    borderBottom: `1px solid ${COLORS.border}`,
                    fontSize: 16,
                    color: COLORS.text,
                  }}
                >
                  {c}
                </button>
              ))}
              <button
                onClick={() => handleMobileNav("craft")}
                style={{
                  display: "block",
                  width: "100%",
                  textAlign: "left",
                  padding: "14px 0",
                  background: "none",
                  border: "none",
                  borderBottom: `1px solid ${COLORS.border}`,
                  fontSize: 16,
                  color: COLORS.text,
                }}
              >
                The Craft
              </button>
              <button
                onClick={() => handleMobileNav("faq")}
                style={{
                  display: "block",
                  width: "100%",
                  textAlign: "left",
                  padding: "14px 0",
                  background: "none",
                  border: "none",
                  fontSize: 16,
                  color: COLORS.text,
                }}
              >
                FAQ
              </button>
            </nav>
          </div>
        </>
      )}
    </header>
  );
}
